"""Compose deterministic social artwork from existing real photos and demo captures."""
from pathlib import Path
import shutil, html, json, hashlib
HERE=Path(__file__).resolve().parent
ROOT=HERE.parent.parent
REF=HERE/'reference'; REF.mkdir(exist_ok=True)
(HERE/'assets').mkdir(exist_ok=True)
# The app's own files are refreshed when this runs inside the repository; on the NAS the copies already in reference/ are used.
refresh=lambda src,dst:(src.is_file() or not dst.is_file()) and shutil.copy2(src,dst)
for name in ['coast','table','window']:
    refresh(ROOT.parent/f'public/wall/memory-{name}.webp',REF/f'{name}.webp')
for name in ['demo-arrival.png','demo-public-wall.png']:
    shutil.copy2(ROOT/'campaigns/respect-host-voice-2026-10-28/reference'/name,REF/name)
refresh(ROOT.parent/'src/assets/logo-long.png',REF/'logo.png')
cards=[]
def art(file,kind,content,pin=False):
    cards.append(f'<article class="art {kind} {"pin" if pin else ""}" data-file="{file}"><div class="eyebrow">DIGISTAYBOOK / A USEFUL WELCOME</div>{content}<footer><img src="reference/logo.png"><span>Illustrative examples · digistaybook.com</span></footer></article>')
art('local-1.png','photo coast','<img class="bg" src="reference/coast.webp"><div class="note"><small>LOCAL FAVORITES / 1 OF 3</small><h1>A place.<br>A reason.<br>A useful detail.</h1><p>Give guests more than a list of places.</p></div>')
art('local-2.png','paper','<small>LOCAL FAVORITES / 2 OF 3</small><h1>Make the tip<br>sound like you.</h1><div class="steps"><p><b>01 / Why you like it</b>A detail only your experience adds.</p><p><b>02 / Who it suits</b>A quiet morning? A rainy afternoon?</p><p><b>03 / What to check</b>Conditions, opening hours or access.</p></div>')
art('local-3.png','dark','<small>LOCAL FAVORITES / 3 OF 3</small><h1>Try one<br>personal note.</h1><blockquote>“We like this walk for a quiet morning. Check the tide and conditions before setting out.”</blockquote><p>Writing example. Add a real recommendation you know.</p><p class="cta">Explore an example guest welcome<br>digistaybook.com/stay/demo-cottage</p>')
art('asked-twice.png','split','<div class="split-photo"><img src="reference/table.webp"></div><div class="split-note"><h1>Asked twice?<br>Give the answer<br>a home.</h1><div class="steps"><p><b>The question</b>What did guests need help finding?</p><p><b>The useful answer</b>One clear line. One real detail.</p><p><b>The place to find it</b>Beside your guest welcome.</p></div></div>')
art('qr-placement.png','paper','<h1>Put the welcome<br>where guests look.</h1><div class="counter"><div class="stand"><b>YOUR<br>GUEST<br>GUIDE</b><span>Display illustration</span></div><div class="folder">WELCOME<br>FOLDER</div></div><div class="tips"><p><b>Clear sightline</b>A welcome counter or folder.</p><p><b>Test the scan</b>Check from a normal standing position.</p></div><p class="fine">Keep your real property QR and private stay details at the property.</p>')
art('rainy-day.png','photo window','<img class="bg" src="reference/window.webp"><div class="note"><small>LOCAL NOTES / RAINY DAYS</small><h1>When the beach<br>is off the list.</h1><p>“We like ___ because ___.<br>Check ___ before you leave.”</p><p class="fine">Fill this with a recommendation you know.</p></div>')
art('guide-1.png','sage','<small>HOUSE-GUIDE STARTER / 1 OF 3</small><h1>A hello.<br>A useful answer.<br>A personal touch.</h1><p>Copy the headings.<br>Make the details your own.</p><div class="strip">WELCOME TO…<br><span>One warm line from you.</span></div>')
art('guide-2.png','paper','<small>HOUSE-GUIDE STARTER / 2 OF 3</small><h1>The answers<br>worth making easy.</h1><div class="steps"><p><b>Arriving</b>Where to park and how to find the right door.</p><p><b>Getting comfortable</b>Wi-Fi, heating and the detail that is easy to miss.</p><p><b>Leaving</b>Checkout time and where the keys belong.</p></div><p class="fine">Use your actual details and the terms that apply to your home.</p>')
art('guide-3.png','dark','<small>HOUSE-GUIDE STARTER / 3 OF 3</small><h1>Then add<br>your voice.</h1><blockquote>One thing we love about this home…</blockquote><blockquote>A local favorite we would suggest…</blockquote><p>Keep the first note short.<br>Put practical details where guests can find them.</p><p class="cta">Explore the guest demo<br>digistaybook.com/stay/demo-cottage</p>')
art('quiet-hours.png','terra','<div class="clock">◷</div><h1>A neighborly<br>note, in one line.</h1><blockquote>“Please bring conversations indoors after [time]; our neighbors start work early.”</blockquote><p>Actual time. Actual place.<br>A true reason.</p><p class="fine">Example wording. Adapt it to your home and the terms that apply.</p>')
art('two-pages.png','paper compare','<h1>Two pages.<br>Two purposes.</h1><div class="phones"><div><h2>During the stay</h2><img src="reference/demo-arrival.png"><p>Welcome + house guidance</p></div><div><h2>Optional public page</h2><img src="reference/demo-public-wall.png"><p>Shared guest memories</p></div></div><p class="fine">Fictional demo. Keep access codes and private stay details out of public pages. An in-stay link is not a guest login.</p>')
art('pin-qr.png','sage','<small>VACATION-RENTAL GUEST GUIDE</small><h1>Where would<br>guests notice<br>your QR display?</h1><div class="strip">THE WELCOME COUNTER<br><span>A clear place to start the stay.</span></div><div class="strip">THE WELCOME FOLDER<br><span>Beside the details guests already look for.</span></div><p>Keep it visible.<br>Test the scan.<br>Check the guest view.</p>',True)
art('pin-pages.png','dark','<small>DIGITAL GUESTBOOK / TWO USEFUL VIEWS</small><h1>House guidance.<br>Guest memories.</h1><div class="strip">DURING THE STAY<br><span>Your welcome and practical notes.</span></div><div class="strip">OPTIONAL PUBLIC PAGE<br><span>A place for shared memories.</span></div><p>Different purposes.<br>Private stay details stay out of public artwork.</p><p class="cta">Explore the fictional guest demo<br>digistaybook.com/stay/demo-cottage</p>',True)
art('pin-setup.png','paper','<small>YOUR FIRST PROPERTY / STARTER CHECKLIST</small><h1>Start with<br>one useful<br>welcome.</h1><div class="steps"><p><b>01 / Write your hello</b>Use your own words.</p><p><b>02 / Add one essential</b>Answer a real practical question.</p><p><b>03 / Check the guest view</b>Read it on your phone.</p><p><b>04 / Test the property QR</b>Give the display a clear home.</p></div>',True)
css='''*{box-sizing:border-box}body{margin:0;background:#ccc}.art{position:relative;width:1080px;height:1350px;background:#f7f2e8;color:#18272a;padding:88px 78px 140px;overflow:hidden;font-family:Georgia,serif;margin:30px}.art.pin{width:1000px;height:1500px}.eyebrow,small,footer,.fine,.cta,.tips,.steps b{font-family:Arial,sans-serif}.eyebrow{font-size:19px;letter-spacing:4px;margin-bottom:70px;position:relative;z-index:2}small{display:block;font-size:19px;letter-spacing:2px;margin-bottom:28px}h1{font-size:83px;line-height:1.06;font-weight:400;letter-spacing:-3px;margin:0 0 50px}p{font-size:35px;line-height:1.4;margin:28px 0}blockquote{font-size:47px;line-height:1.3;border-left:6px solid #b4472a;padding:20px 0 20px 32px;margin:40px 0}.dark{background:#18272a;color:#f7f2e8}.terra{background:#a64026;color:#fff8ed}.sage{background:#dae2d8}.steps p{font-size:31px;border-top:1px solid #aaa99c;padding-top:24px;margin:24px 0}.steps b{display:block;font-size:23px;letter-spacing:1px;margin-bottom:12px;color:#a64026}.fine{font-size:22px;line-height:1.4}.cta{font-size:24px;margin-top:60px}.strip{padding:28px 32px;background:#fffaf0;color:#18272a;margin:28px 0;font:23px Arial,sans-serif;letter-spacing:2px}.strip span{display:block;font:30px/1.35 Georgia,serif;letter-spacing:0;margin-top:16px}footer{position:absolute;bottom:0;left:0;width:100%;padding:27px 44px;background:#f7f2e8;display:flex;align-items:center;justify-content:space-between;color:#444;font-size:16px;height:105px}footer img{width:260px;height:55px;object-fit:contain}.bg{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}.photo .eyebrow{background:#f7f2e8;display:inline-block;padding:15px;top:-35px;left:-20px}.note{position:absolute;bottom:180px;left:65px;right:65px;background:#f7f2e8;padding:50px}.note h1{font-size:76px}.note p{font-size:31px}.split{padding:0}.split .eyebrow{position:absolute;top:55px;left:45px;background:#f7f2e8;padding:12px;font-size:15px}.split-photo{height:445px;width:100%}.split-photo img{width:100%;height:100%;object-fit:cover}.split-note{padding:44px 65px}.split h1{font-size:68px;margin-bottom:25px}.split .steps p{font-size:27px;margin:15px 0;padding-top:15px}.split .steps b{font-size:19px}.counter{position:relative;height:395px;border-bottom:20px solid #b8a284;background:#e8e0cf;margin:30px 0 35px}.stand{position:absolute;left:100px;bottom:0;background:#fffdf6;border:6px solid #b4472a;padding:30px 35px;width:255px;transform:rotate(-6deg);font:40px/1.1 Arial}.stand span{display:block;font:17px Arial;margin-top:25px}.folder{position:absolute;right:75px;bottom:0;background:#cbb991;padding:45px 30px;width:300px;transform:rotate(7deg);font:32px Arial}.tips{display:flex;gap:40px}.tips p{font-size:25px;flex:1}.tips b{display:block;margin-bottom:10px}.clock{position:absolute;right:65px;top:130px;font:260px Georgia;color:#d7aa75;opacity:.4}.terra h1{position:relative;margin-top:125px}.terra blockquote{border-color:#f1c4a5}.phones{display:flex;gap:35px}.phones>div{flex:1;min-width:0}.phones h2{font:25px Arial;height:45px}.phones img{height:500px;width:100%;object-fit:cover;object-position:top;border:10px solid #18272a;border-radius:25px}.phones p{font-size:25px}.compare h1{font-size:78px;margin-bottom:25px}.compare .fine{margin-top:45px}.pin h1{font-size:82px}.pin .eyebrow{margin-bottom:85px}'''
(HERE/'artwork.html').write_text('<!doctype html><meta charset="utf-8"><title>DigiStayBook social artwork</title><style>'+css+'</style>'+''.join(cards),encoding='utf-8')
records=[]
for f in REF.iterdir():
    records.append(dict(file=f.name,sha256=hashlib.sha256(f.read_bytes()).hexdigest()))
(HERE/'ARTWORK_PROVENANCE.json').write_text(json.dumps(dict(created='2026-10-28',method='Ordinary HTML/CSS composition and browser rendering; no generated photography.',photo_sources='Existing public/wall/memory-coast.webp, memory-table.webp and memory-window.webp; credits in docs/demo-photo-credits.md. Licence websites not independently rechecked in this run.',demo_sources='Current local campaign captures from respect-host-voice-2026-10-28; fictional demonstration, not real customer usage.',files=records),indent=2),encoding='utf-8')
print(f'Prepared {len(cards)} deterministic artwork boards.')
